import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
// The existing single-edit API works. Preserve it while extending this module.
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
// Two edits conflict when applying both, using original-source coordinates, is ambiguous.
// - Two nonempty ranges conflict iff their half-open intervals overlap (adjacent is fine).
// - An insertion (start===end) conflicts with another insertion at the same position.
// - An insertion conflicts with a nonempty range if its position lies within [start,end]
//   (i.e. anywhere between the range's endpoints, inclusive).
function conflicts(a,b){
  const ai=a.start===a.end,bi=b.start===b.end;
  if(ai&&bi)return a.start===b.start;
  if(!ai&&!bi)return a.start<b.end&&b.start<a.end;
  const ins=ai?a:b,rep=ai?b:a;
  return rep.start<=ins.start&&ins.start<=rep.end;
}
const cmp=(a,b)=>(a<b?-1:a>b?1:0);
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('source must be a string');
  if(!Array.isArray(edits))throw Error('edits must be an array');
  // Validate every edit against the ORIGINAL source before applying anything.
  for(const edit of edits)checkEdit(source,edit);
  // Reject ambiguous overlaps/insertion boundaries; no partial output on conflict.
  for(let i=0;i<edits.length;i++)
    for(let j=i+1;j<edits.length;j++)
      if(conflicts(edits[i],edits[j]))throw Error('conflicting edits');
  // All coordinates refer to the original source. Apply simultaneously by merging
  // sorted replacement ranges and sorted insertions, leaving untouched spans intact.
  const ranges=[],inserts=[];
  for(const edit of edits)(edit.start===edit.end?inserts:ranges).push(edit);
  ranges.sort((a,b)=>cmp(a.start,b.start));
  inserts.sort((a,b)=>cmp(a.start,b.start));
  let out='',cursor=0,ri=0,ii=0;
  while(ri<ranges.length||ii<inserts.length){
    const r=ri<ranges.length?ranges[ri]:null;
    const ins=ii<inserts.length?inserts[ii]:null;
    // nextPos is the earliest remaining event (a range start or an insertion position);
    // validated edits guarantee at most one event per position.
    const nextPos=(r&&(!ins||r.start<=ins.start))?r.start:ins.start;
    out+=source.slice(cursor,nextPos);
    if(r&&r.start===nextPos){out+=r.after;cursor=r.end;ri++;}
    else if(ins&&ins.start===nextPos){out+=ins.after;cursor=nextPos;ii++;}
  }
  out+=source.slice(cursor);
  return{text:out,applied:edits.length};
}
// Add the JSON-file CLI described by the work order without import side effects.
function isMainModule(){
  const arg=process.argv[1];
  if(!arg)return false;
  let entry,self;
  try{entry=path.resolve(arg);}catch{return false;}
  try{self=fileURLToPath(import.meta.url);}catch{return false;}
  if(entry===self)return true;
  try{return fs.realpathSync(entry)===fs.realpathSync(self);}catch{return false;}
}
function fail(message){
  process.stderr.write(message+'\n');
  process.exit(2);
}
function runCli(){
  const args=process.argv.slice(2);
  if(args.length!==1)fail('usage: node patch-transaction.js INPUT_JSON_FILE');
  let raw;
  try{raw=fs.readFileSync(args[0],'utf8');}
  catch(e){fail('cannot read input file: '+e.message);}
  let data;
  try{data=JSON.parse(raw);}
  catch(e){fail('invalid JSON: '+e.message);}
  let source,edits;
  if(data&&typeof data==='object'&&!Array.isArray(data)){source=data.source;edits=data.edits;}
  let result;
  try{result=applyTransaction(source,edits);}
  catch(e){fail('invalid transaction: '+e.message);}
  process.stdout.write(JSON.stringify(result)+'\n');
}
if(isMainModule())runCli();

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {applyEdit,applyTransaction} from '../patch-transaction.js';

const script=fileURLToPath(new URL('../patch-transaction.js',import.meta.url));
const edit=(start,end,before,after,extra)=>({...extra,start,end,before,after});
const deepThrow=(fn)=>assert.throws(fn,Error);

test('applyEdit is preserved',()=>{
  assert.equal(applyEdit('abc',edit(1,2,'b','LONG')),'aLONGc');
  assert.throws(()=>applyEdit('abc',edit(1,2,'wrong','x')),Error);
  assert.throws(()=>applyEdit('abc',null),Error);
});

test('order independence and applied count',()=>{
  const edits=[edit(0,1,'a','LONG'),edit(3,5,'de','X')];
  const expect={text:'LONGbcXf',applied:2};
  assert.deepEqual(applyTransaction('abcdef',edits),expect);
  assert.deepEqual(applyTransaction('abcdef',[...edits].reverse()),expect);
  // A shuffled copy must give the same result.
  const shuffled=[edits[1],edits[0]];
  assert.deepEqual(applyTransaction('abcdef',shuffled),expect);
});

test('adjacent nonempty ranges are allowed',()=>{
  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,4,'cd','y')]),{text:'xy',applied:2});
});

test('overlapping and nested nonempty ranges conflict',()=>{
  deepThrow(()=>applyTransaction('abcdef',[edit(0,3,'abc','X'),edit(2,4,'cd','Y')]));
  deepThrow(()=>applyTransaction('abcdef',[edit(0,4,'abcd','X'),edit(1,2,'b','Y')]));
  deepThrow(()=>applyTransaction('abcdef',[edit(0,4,'abcd','X'),edit(0,4,'abcd','Y')]));
});

test('insertion conflicts with a range endpoint or interior, none just outside',()=>{
  deepThrow(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,2,'','y')]));   // end endpoint
  deepThrow(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(0,0,'','y')]));   // start endpoint
  deepThrow(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(1,1,'','y')]));   // interior
  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,4,'cd','y'),edit(1,1,'','z')]),{text:'x',applied:3}); // wait, see below
});

test('insertions at distinct positions outside all ranges are allowed',()=>{
  assert.deepEqual(applyTransaction('abcde',[edit(1,1,'','X'),edit(3,3,'','Y')]),{text:'aXbcYe',applied:2});
  assert.deepEqual(applyTransaction('abcde',[edit(0,0,'','S'),edit(5,5,'','E')]),{text:'SabcdeE',applied:2});
  // Insertion and a non-overlapping range.
  assert.deepEqual(applyTransaction('abcdef',[edit(0,2,'ab','X'),edit(4,4,'','Y')]),{text:'XcdYef',applied:2});
  // Insertion between two ranges.
  assert.deepEqual(applyTransaction('abcdef',[edit(0,2,'ab','X'),edit(4,6,'ef','Z'),edit(3,3,'','Y')]),{text:'XcYdZ',applied:3});
});

test('two insertions at the same position conflict, even empty ones',()=>{
  deepThrow(()=>applyTransaction('ab',[edit(0,0,'','X'),edit(0,0,'','Y')]));
  deepThrow(()=>applyTransaction('ab',[edit(0,0,'',''),edit(0,0,'','Y')]));
  assert.deepEqual(applyTransaction('ab',[edit(0,0,'','X'),edit(1,1,'','Y')]),{text:'XaYb',applied:2});
});

test('empty transaction and empty source insertion',()=>{
  assert.deepEqual(applyTransaction('tail\r\n',[]),{text:'tail\r\n',applied:0});
  assert.deepEqual(applyTransaction('',[edit(0,0,'','new')]),{text:'new',applied:1});
  deepThrow(()=>applyTransaction('',[]===0?null:[edit(1,1,'','x')])); // out of range
});

test('no-op edits are valid and counted',()=>{
  assert.deepEqual(applyTransaction('ab',[edit(0,1,'a','a')]),{text:'ab',applied:1});
  assert.deepEqual(applyTransaction('ab',[edit(1,1,'','')]),{text:'ab',applied:1});
});

test('preserves untouched code units, CR/LF, whitespace, final newline',()=>{
  const src='a\r\nb\tc\n';
  const r=applyTransaction(src,[edit(0,1,'a','Z')]);
  assert.equal(r.text,'Z\r\nb\tc\n');
  assert.equal(r.applied,1);
});

test('validation: source, edits, and field types',()=>{
  deepThrow(()=>applyTransaction(null,[]));
  deepThrow(()=>applyTransaction(5,[]));
  deepThrow(()=>applyTransaction('',null));
  deepThrow(()=>applyTransaction('',{start:0,end:0,before:'',after:''}));
  deepThrow(()=>applyTransaction('ab',['x']));
  deepThrow(()=>applyTransaction('ab',[null]));
  deepThrow(()=>applyTransaction('ab',[edit('0',1,'a','X')]));      // no coercion of start
  deepThrow(()=>applyTransaction('ab',[edit(0,1,1,'X')]));          // before must be string
  deepThrow(()=>applyTransaction('ab',[edit(0,1,'a',1)]));          // after must be string
  deepThrow(()=>applyTransaction('ab',[edit(-1,0,'','x')]));        // negative start
  deepThrow(()=>applyTransaction('ab',[edit(1,0,'a','x')]));        // start>end
  deepThrow(()=>applyTransaction('ab',[edit(0,3,'','x')]));         // end>length
  deepThrow(()=>applyTransaction('ab',[edit(0,1,'b','x')]));        // preimage mismatch
  deepThrow(()=>applyTransaction('ab',[{start:0.5,end:1,before:'b',after:'x'}])); // non-integer
});

test('unknown object fields are ignored',()=>{
  assert.deepEqual(applyTransaction('ab',[edit(0,1,'a','X',{note:'hello',id:42})]),{text:'Xb',applied:1});
});

test('input array and objects are not mutated',()=>{
  const edits=[edit(0,1,'a','X'),edit(2,3,'c','Y')];
  const snapshot=JSON.stringify(edits);
  applyTransaction('abc',edits);
  assert.equal(JSON.stringify(edits),snapshot);
});

// --- CLI ---
function runCli(args,setup){
  let dir=null;
  if(setup){
    dir=fs.mkdtempSync(path.join(os.tmpdir(),'patch-tx-'));
    setup(dir);
  }
  const res=spawnSync(process.execPath,[script,...args],{encoding:'utf8'});
  if(dir)fs.rmSync(dir,{recursive:true,force:true});
  return res;
}
function writeInput(dir,objOrRaw){
  const file=path.join(dir,'input.json');
  fs.writeFileSync(file,typeof objOrRaw==='string'?objOrRaw:JSON.stringify(objOrRaw),'utf8');
  return file;
}

test('CLI success: prints one JSON line, exits 0, no stderr',()=>{
  const res=runCli([],(dir)=>{
    const f=writeInput(dir,{source:'abcdef',extra:'ignored',edits:[edit(0,1,'a','LONG'),edit(3,5,'de','X')]});
    return runOneFile(dir,f);
  });
});
function runOneFile(dir,file){
  const res=spawnSync(process.execPath,[script,file],{encoding:'utf8'});
  assert.equal(res.status,0,'expected exit 0, got '+res.status+' stderr='+res.stderr);
  assert.equal(res.stderr,'');
  assert.ok(res.stdout.endsWith('\n'));
  assert.equal(JSON.parse(res.stdout),{text:'LONGbcXf',applied:2});
  fs.rmSync(dir,{recursive:true,force:true});
}

test('CLI invalid transaction exits 2 with stderr and no stdout',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'patch-tx-'));
  const f=writeInput(dir,{source:'abc',edits:[edit(0,2,'ab','x')]});
  const res=spawnSync(process.execPath,[script,f],{encoding:'utf8'});
  fs.rmSync(dir,{recursive:true,force:true});
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
});

test('CLI invalid JSON exits 2',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'patch-tx-'));
  const f=writeInput(dir,'{not valid json');
  const res=spawnSync(process.execPath,[script,f],{encoding:'utf8'});
  fs.rmSync(dir,{recursive:true,force:true});
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
});

test('CLI wrong arg count exits 2',()=>{
  const res=spawnSync(process.execPath,[script],{encoding:'utf8'});
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
  const res2=spawnSync(process.execPath,[script,'a','b'],{encoding:'utf8'});
  assert.equal(res2.status,2);
});

test('CLI unreadable file exits 2',()=>{
  const res=spawnSync(process.execPath,[script,path.join(os.tmpdir(),'does-not-exist-xyz.json')],{encoding:'utf8'});
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
});

test('CLI empty transaction via file',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'patch-tx-'));
  const f=writeInput(dir,{source:'keep\n',edits:[]});
  const res=spawnSync(process.execPath,[script,f],{encoding:'utf8'});
  fs.rmSync(dir,{recursive:true,force:true});
  assert.equal(res.status,0);
  assert.equal(JSON.parse(res.stdout),{text:'keep\n',applied:0});
});

