const deepThrow=(fn)=>assert.throws(fn,Error);

// Write content to a temp file in os.tmpdir(), run the CLI on it, clean up, return result.
function runCliOnFile(content){
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'patch-tx-'));
  const file=path.join(dir,'input.json');
  fs.writeFileSync(file,typeof content==='string'?content:JSON.stringify(content),'utf8');
  const res=spawnSync(process.execPath,[script,file],{encoding:'utf8'});
  fs.rmSync(dir,{recursive:true,force:true});
  return res;
}
const runCliArgs=(args)=>spawnSync(process.execPath,[script,...args],{encoding:'utf8'});

