import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {applyEdit,applyTransaction} from '../patch-transaction.js';

const script=fileURLToPath(new URL('../patch-transaction.js',import.meta.url));
const edit=(start,end,before,after,extra)=>({...extra,start,end,before,after});
const deepThrow=(fn)=>assert.throws(fn,Error);

// Write content to a temp file in os.tmpdir(), run the CLI on it, clean up, return result.
function runCliOnFile(content){
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'patch-tx-'));
  const file=path.join(dir,'input.json');
  fs.writeFileSync(file,typeof content==='string'?content:JSON.stringify(content),'utf8');
  const res=spawnSync(process.execPath,[script,file],{encoding:'utf8'});
  fs.rmSync(dir,{recursive:true,force:true});
  return res;
}
const runCliArgs=(args)=>spawnSync(process.execPath,[script,...args],{encoding:'utf8'});

test('applyEdit is preserved',()=>{
  assert.equal(applyEdit('abc',edit(1,2,'b','LONG')),'aLONGc');
  deepThrow(()=>applyEdit('abc',edit(1,2,'wrong','x')));
  deepThrow(()=>applyEdit('abc',null));
});

test('order independence and applied count',()=>{
  const edits=[edit(0,1,'a','LONG'),edit(3,5,'de','X')];
  const expect={text:'LONGbcXf',applied:2};
  assert.deepEqual(applyTransaction('abcdef',edits),expect);
  assert.deepEqual(applyTransaction('abcdef',[...edits].reverse()),expect);
});

test('adjacent nonempty ranges are allowed',()=>{
  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,4,'cd','y')]),{text:'xy',applied:2});
});

test('overlapping and nested nonempty ranges conflict',()=>{
  deepThrow(()=>applyTransaction('abcdef',[edit(0,3,'abc','X'),edit(2,4,'cd','Y')]));
  deepThrow(()=>applyTransaction('abcdef',[edit(0,4,'abcd','X'),edit(1,2,'b','Y')]));
  deepThrow(()=>applyTransaction('abcdef',[edit(0,4,'abcd','X'),edit(0,4,'abcd','Y')]));
});

test('insertion vs range: endpoint/interior conflict, just-outside allowed',()=>{
  deepThrow(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,2,'','y')]));  // end endpoint
  deepThrow(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(0,0,'','y')]));  // start endpoint
  deepThrow(()=>applyTransaction('abcd',[edit(0,2,'ab','x'),edit(1,1,'','y')]));  // interior
  assert.deepEqual(applyTransaction('abcd',[edit(2,4,'cd','y'),edit(1,1,'','z')]),{text:'azby',applied:2});
});

test('insertions at distinct positions outside all ranges are allowed',()=>{
  assert.deepEqual(applyTransaction('abcde',[edit(1,1,'','X'),edit(3,3,'','Y')]),{text:'aXbcYde',applied:2});
  assert.deepEqual(applyTransaction('abcde',[edit(0,0,'','S'),edit(5,5,'','E')]),{text:'SabcdeE',applied:2});
  assert.deepEqual(applyTransaction('abcdef',[edit(0,2,'ab','X'),edit(4,4,'','Y')]),{text:'XcdYef',applied:2});
  assert.deepEqual(applyTransaction('abcdef',[edit(0,2,'ab','X'),edit(4,6,'ef','Z'),edit(3,3,'','Y')]),{text:'XcYdZ',applied:3});
});

test('two insertions at the same position conflict, even empty ones',()=>{
  deepThrow(()=>applyTransaction('ab',[edit(0,0,'','X'),edit(0,0,'','Y')]));
  deepThrow(()=>applyTransaction('ab',[edit(0,0,'',''),edit(0,0,'','Y')]));
  assert.deepEqual(applyTransaction('ab',[edit(0,0,'','X'),edit(1,1,'','Y')]),{text:'XaYb',applied:2});
});

test('empty transaction and empty source insertion',()=>{
  assert.deepEqual(applyTransaction('tail\r\n',[]),{text:'tail\r\n',applied:0});
  assert.deepEqual(applyTransaction('',[edit(0,0,'','new')]),{text:'new',applied:1});
  deepThrow(()=>applyTransaction('',[edit(1,1,'','x')])); // position beyond length
});

test('no-op edits are valid and counted',()=>{
  assert.deepEqual(applyTransaction('ab',[edit(0,1,'a','a')]),{text:'ab',applied:1});
  assert.deepEqual(applyTransaction('ab',[edit(1,1,'','')]),{text:'ab',applied:1});
});

test('preserves untouched code units, CR/LF, whitespace, final newline',()=>{
  const r=applyTransaction('a\r\nb\tc\n',[edit(0,1,'a','Z')]);
  assert.equal(r.text,'Z\r\nb\tc\n');
  assert.equal(r.applied,1);
});

test('validation: source, edits, and field types',()=>{
  deepThrow(()=>applyTransaction(null,[]));
  deepThrow(()=>applyTransaction(5,[]));
  deepThrow(()=>applyTransaction('',null));
  deepThrow(()=>applyTransaction('',{start:0,end:0,before:'',after:''}));
  deepThrow(()=>applyTransaction('ab',['x']));
  deepThrow(()=>applyTransaction('ab',[null]));
  deepThrow(()=>applyTransaction('ab',[edit('0',1,'a','X')]));   // start must be a number
  deepThrow(()=>applyTransaction('ab',[edit(0,1,1,'X')]));       // before must be a string
  deepThrow(()=>applyTransaction('ab',[edit(0,1,'a',1)]));       // after must be a string
  deepThrow(()=>applyTransaction('ab',[edit(-1,0,'','x')]));     // negative start
  deepThrow(()=>applyTransaction('ab',[edit(1,0,'a','x')]));     // start>end
  deepThrow(()=>applyTransaction('ab',[edit(0,3,'','x')]));      // end>length
  deepThrow(()=>applyTransaction('ab',[edit(0,1,'b','x')]));     // preimage mismatch
  deepThrow(()=>applyTransaction('ab',[edit(0.5,1,'b','x')]));   // non-integer offset
});

test('unknown object fields are ignored',()=>{
  assert.deepEqual(applyTransaction('ab',[edit(0,1,'a','X',{note:'hello',id:42})]),{text:'Xb',applied:1});
});

test('input array and objects are not mutated',()=>{
  const edits=[edit(0,1,'a','X'),edit(2,3,'c','Y')];
  const snapshot=JSON.stringify(edits);
  applyTransaction('abc',edits);
  assert.equal(JSON.stringify(edits),snapshot);
});

// --- CLI ---
test('CLI success: one JSON line, exit 0, empty stderr',()=>{
  const res=runCliOnFile({source:'abcdef',extra:'ignored',edits:[edit(0,1,'a','LONG'),edit(3,5,'de','X')]});
  assert.equal(res.status,0,'status='+res.status+' stderr='+res.stderr);
  assert.equal(res.stderr,'');
  assert.ok(res.stdout.endsWith('\n'));
  assert.deepEqual(JSON.parse(res.stdout),{text:'LONGbcXf',applied:2});
});

test('CLI empty transaction via file',()=>{
  const res=runCliOnFile({source:'keep\n',edits:[]});
  assert.equal(res.status,0);
  assert.deepEqual(JSON.parse(res.stdout),{text:'keep\n',applied:0});
});

test('CLI invalid transaction exits 2, nonempty stderr, no stdout',()=>{
  const res=runCliOnFile({source:'abc',edits:[edit(0,2,'XY','x')]}); // preimage mismatch
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
});

test('CLI invalid JSON exits 2',()=>{
  const res=runCliOnFile('{not valid json');
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
});

test('CLI wrong arg count exits 2',()=>{
  const res=runCliArgs([]);
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
  assert.equal(runCliArgs(['a','b']).status,2);
});

test('CLI unreadable file exits 2',()=>{
  const res=runCliArgs([path.join(os.tmpdir(),'does-not-exist-xyz.json')]);
  assert.equal(res.status,2);
  assert.ok(res.stderr.length>0);
  assert.equal(res.stdout,'');
});

test('importing the module does not run the CLI',()=>{
  // A fresh ESM import must not write to stdout/stderr or exit nonzero.
  const res=spawnSync(process.execPath,['--input-type=module','-e',
    `await import('file://${script}');`],{encoding:'utf8'});
  assert.equal(res.status,0,'stderr='+res.stderr);
  assert.equal(res.stdout,'');
  assert.equal(res.stderr,'');
});

